// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address beneficiary) public {
        vm.assume(owner != address(0));
        vm.assume(beneficiary != address(0));
        vm.assume(owner != beneficiary);
        // Deploy a helper that reverts on receiving ETH
        Reverter reverter = new Reverter(address(c));
        // Prank as the owner and call sudicideAnyone with selfdestruct beneficiary = msg.sender (owner)
        vm.prank(owner);
        // The call will selfdestruct and attempt to send ETH to msg.sender (owner)
        // Since owner is an EOA, the receive succeeds, so no revert
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sudicideAnyone.selector));
        // In the correct version, success == true because ETH sent to EOA owner succeeds.
        // In the buggy version, selfdestruct sends to smartfix_owner (which is reverter),
        // reverter's receive() reverts, causing the call to fail (success == false).
        assertTrue(success);
    }
}

contract Reverter {
    constructor(address target) {
        // To become smartfix_owner in the context of C, we need to be the deployer
        // But C inherits SmartFix which sets smartfix_owner = msg.sender of C's deployment.
        // We can't change that post-deployment. Instead, this approach is flawed.
    }
    fallback() external payable {
        revert("Reverter");
    }
    receive() external payable {
        revert("Reverter");
    }
}

