pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address beneficiary) public {
        vm.assume(owner != address(0));
        vm.assume(beneficiary != address(0));
        vm.assume(owner != beneficiary);
        // Transfer ownership to fuzzed owner
        vm.prank(c.smartfix_owner());
        c.smartfix_owner = owner;
        // Fund the contract
        vm.deal(address(c), 1 ether);
        // Deploy a helper that reverts on receive; use it as beneficiary
        Reverter rev = new Reverter();
        // The bug sends ETH to smartfix_owner (owner), so set smartfix_owner to the reverter
        // Only the buggy version will attempt to send to smartfix_owner; the reference sends to msg.sender (owner)
        // In the bug, the selfdestruct recipient is `payable(smartfix_owner)`, so we make smartfix_owner the reverter
        vm.prank(owner);
        c.smartfix_owner = address(rev);
        // Now owner calls sudicideAnyone. Reference sends to msg.sender (owner), which succeeds.
        // Bug sends to smartfix_owner (rev), which reverts.
        bool ok;
        vm.prank(owner);
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
contract Reverter { fallback() external payable { revert(); } }
